style.css:
@-moz-document domain("docs.google.com") {
/* Background */
  body, div.kix-appview-editor {
    background-color: #2f3136 !important;
    color: #dcddde !important;
  }

  /* Main document canvas */
  .kix-canvas-tile-content, .kix-page {
    background-color: #36393f !important;
    box-shadow: none !important;
  }

  /* Toolbar and menu bar */
  .docs-titlebar, .kix-documenttoolbar, .docs-menubar, .docs-material, .docs-title-input-label {
    background-color: #202225 !important;
    color: #fff !important;
    border-bottom: 1px solid #2c2f33 !important;
  }

  .goog-toolbar-button, .goog-menu, .goog-control {
    background-color: #2f3136 !important;
    color: #dcddde !important;
    border: none !important;
  }

  /* Toolbar icons hover */
  .goog-toolbar-button:hover, .goog-control:hover {
    background-color: #40444b !important;
  }

  /* Sidebar and other UI panels */
  .kix-sidebar, .kix-zoomdocumentplugin {
    background-color: #2f3136 !important;
    color: #dcddde !important;
  }

  /* Comments and suggestions */
  .docs-comments-sidebar, .docs-comment {
    background-color: #2c2f33 !important;
    color: #dcddde !important;
    border-color: #202225 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 12px;
  }

  ::-webkit-scrollbar-track {
    background: #202225;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #7289da;
    border-radius: 6px;
    border: 3px solid #202225;
  }

  /* Fix for editable areas */
  .kix-wordhtmlgenerator-word-node {
    color: #dcddde !important;
  }
}
